        const tabContents = document.getElementById('tabContents');
        const stats = document.getElementById('stats');

        // 文件上传处理
        fileInput.addEventListener('change', function(e) {
            const files = Array.from(e.target.files);

            if (files.length === 0) return;

            files.forEach((file, index) => {
                const reader = new FileReader();

                reader.onload = function(event) {
                    const photoData = {
                        id: Date.now() + index,
                        name: file.name,
                        data: event.target.result,
                        note: '',
                        uploadedAt: new Date().toLocaleString('zh-CN')
                    };

                    photos.push(photoData);
                    renderGallery();
                };

                reader.readAsDataURL(file);
            });

            // 清空 input，允许重复上传同一文件
            fileInput.value = '';
        });

        // 渲染相册
        function renderGallery() {
            tabsContainer.innerHTML = '';
            tabContents.innerHTML = '';

            if (photos.length === 0) {
                stats.textContent = '暂无照片，请上传校园生活照片';
                return;
            }

            stats.textContent = `共 ${photos.length} 张照片`;

            // 渲染选项卡按钮
            photos.forEach((photo, index) => {
                const tabBtn = document.createElement('button');
                tabBtn.className = 'tab-btn';
                tabBtn.textContent = `${index + 1}. ${photo.name}`;
                tabBtn.dataset.index = index;
                tabBtn.addEventListener('click', () => openTab(index));
                tabsContainer.appendChild(tabBtn);
            });

            // 默认打开第一个选项卡
            if (photos.length > 0) {
                openTab(0);
            }
        }

        // 打开选项卡
        function openTab(index) {
            currentPhotoIndex = index;

            // 更新按钮状态
            const buttons = tabsContainer.querySelectorAll('.tab-btn');
            buttons.forEach(btn => btn.classList.remove('active'));
            buttons[index].classList.add('active');

            // 渲染内容
            renderTabContent(index);
        }

        // 渲染选项卡内容
        function renderTabContent(index) {
            const photo = photos[index];

            tabContents.innerHTML = `
                <div class="tab-content active">
                    <div class="detail-view">
                        <img src="${photo.data}" alt="${photo.name}" class="detail-image">

                        <div class="detail-info">
                            <h3>📝 备注</h3>
                            <textarea 
                                class="note-input" 
                                placeholder="在这里写下关于这张照片的回忆..."
                                data-note-index="${index}">${photo.note}</textarea>

                            <button class="save-btn" onclick="saveNote(${index})">💾 保存备注</button>
                            <button class="delete-btn" onclick="deletePhoto(${index})">🗑️ 删除照片</button>
                        </div>
                    </div>
                </div>
            `;
        }

        // 保存备注
        function saveNote(index) {
            const textarea = document.querySelector(`[data-note-index="${index}"]`);
            const note = textarea.value.trim();

            photos[index].note = note;

            // 保存到 localStorage
            saveToLocalStorage();

            alert('备注已保存！');
        }

        // 删除照片
        function deletePhoto(index) {
            if (confirm('确定要删除这张照片吗？')) {
                photos.splice(index, 1);
                renderGallery();

                // 如果删除的是当前查看的照片，打开第一个
                if (photos.length > 0) {
                    openTab(0);
                }
            }
        }

        // 保存到 localStorage
        function saveToLocalStorage() {
            const data = JSON.stringify(photos);
            try {
                localStorage.setItem('campusPhotos', data);
            } catch (e) {
                console.log('localStorage 不可用或空间不足');
            }
        }

        // 从 localStorage 加载
        function loadFromLocalStorage() {
            try {
                const data = localStorage.getItem('campusPhotos');
                if (data) {
                    photos = JSON.parse(data);
                    renderGallery();
                }
            } catch (e) {
                console.error('加载数据失败:', e);
            }
        }

        // 页面加载时从 localStorage 加载数据
        loadFromLocalStorage();
    </script>
</body>
</html>
</parameter>
</function>
</tool_call>

